     SetThreadLocale has not been called - which is a very frequent case -
     the value of GetThreadLocale() ignores past calls to 'setlocale'.  */
  return NULL;

const char *
gl_locale_name_environ (_GL_UNUSED int category, const char *categoryname)
{
  /* Setting of LC_ALL overrides all other.  */
  {
    const char *retval = getenv ("LC_ALL");
    if (retval != NULL && retval[0] != '\0')
      return retval;
  }
  /* Next comes the name of the desired category.  */
  {
    const char *retval = getenv (categoryname);
    if (retval != NULL && retval[0] != '\0')
      return retval;
  }
  /* Last possibility is the LANG environment variable.  */
  {
    const char *retval = getenv ("LANG");
    if (retval != NULL && retval[0] != '\0')
      {
#if HAVE_CFPREFERENCESCOPYAPPVALUE
        /* Mac OS X 10.2 or newer.
           Ignore invalid LANG value set by the Terminal application.  */
        if (!streq (retval, "UTF-8"))
#endif
#if defined __CYGWIN__
        /* Cygwin.
           Ignore dummy LANG value set by ~/.profile.  */
         if (!streq (retval, "C.UTF-8"))
#endif
          return retval;
      }
  }

  return NULL;

const char *
gl_locale_name_posix (int category, const char *categoryname)
{
  if (category == LC_ALL)
    /* Invalid argument.  */
    abort ();
  const char *name = gl_locale_name_posix_unsafe (category, categoryname);
  if (name != NULL)
    return struniq (name);
  return NULL;
}

